html:
{% if letter_head %}
    {{ letter_head }}
{% endif %}

<!-- ORDER # + LICENSE HEADER -->
<div style="margin-top: 10px;">
    <div class="print-heading" style="text-align: left; border-bottom: none !important;">
        <small class="sub-heading"
               style="font-size: 18px; font-weight: bold; margin-top: 4px; display: block; color: #7b2fbf;">
            Invoice # {{ _(doc.name) }}
        </small>
        <small class="sub-heading"
               style="font-size: 18px; font-weight: bold; margin-top: 4px; display: block; color: #7b2fbf;">
            License : {{ _(doc.custom_license) }}
        </small>
    </div>
</div>

<style>
    .margin-space { margin-top: 5px; margin-bottom: 5px; }
    .padding-space { padding-top: 5px; padding-bottom: 5px; }
    .group-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 10px;
        margin-bottom: 20px;
        font-size: 11px;
    }
    .group-table th, .group-table td {
        border: 1px solid #000;
        padding: 5px;
        text-align: left;
    }
    .group-table th {
        background-color: #f2f2f2;
    }
</style>

<!-- CUSTOMER + COMPANY INFO -->
<div style="display: flex; justify-content: space-between; align-items: flex-start;">
    <div style="text-align: left; line-height: 1.4;">
        <div style="font-weight: bold; color: #000000; font-size: 14px;">
            {{ doc.customer_name }}
        </div>
        <div style="color: #555555; font-size: 14px;">
            Order Type: {{ doc.custom_sales_order_type }}
        </div>
    </div>
    <div style="text-align: right; line-height: 1.4;">
        <div style="font-weight: bold; color: #000000; font-size: 14px;">
            MOTLEY TERPZ, LLC
        </div>
        <div style="color: #555555; font-size: 14px;">
            California
        </div>
        <div style="color: #555555; font-size: 14px;">
            310-780-4784
        </div>
    </div>
</div>

<div class="margin-space"></div>
<div class="padding-space"></div>

<!-- ORDER DATE + DELIVERY DATE -->
<div style="display: flex; justify-content: space-between; align-items: flex-start;">
    <div style="text-align: left; line-height: 1.4;">
        <div style="font-weight: bold; color: #000000; font-size: 14px;">
            ORDER DATE
        </div>
        <div style="color: #555555; font-size: 14px;">
            {{ frappe.format_date(doc.transaction_date) }}
        </div>
    </div>
    <div style="text-align: right; line-height: 1.4;">
        <div style="font-weight: bold; color: #000000; font-size: 14px;">
            DELIVERY DATE
        </div>
        <div style="color: #555555; font-size: 14px;">
            {{ frappe.format_date(doc.delivery_date) }}
        </div>
    </div>
</div>

<div class="margin-space"></div>
<div class="padding-space"></div>

<!-- ITEMS TABLE WITH GENERALIZATION GROUPING -->
{% set grouped = {} %}
{% set normal_items = [] %}

{% for item in doc.items %}
    {% if item.custom_generalization %}
        {% if item.custom_generalization in grouped %}
            {% set _ = grouped[item.custom_generalization].update({
                "rate": grouped[item.custom_generalization].rate + item.rate,
                "qty": grouped[item.custom_generalization].qty + item.qty,
                "amount": grouped[item.custom_generalization].amount + item.amount
            }) %}
        {% else %}
            {% set _ = grouped.update({
                item.custom_generalization: {
                    "description": item.custom_generalization,
                    "rate": item.rate,
                    "qty": item.qty,
                    "amount": item.amount,
                    "uom": item.uom,
                    "type": item.item_group
                }
            }) %}
        {% endif %}
    {% else %}
        {% set _ = normal_items.append(item) %}
    {% endif %}
{% endfor %}

<table class="table table-bordered" width="100%" cellspacing="0" cellpadding="6">
    <thead style="background-color:#d9a7ff;">
        <tr>
            <th style="width:5%; text-align:center;">Sr</th>
            <th style="width:40%;">Description</th>
            <th style="width:15%; text-align:center;">Type</th>
            <th style="width:15%; text-align:center;">Quantity</th>
            <th style="width:12%; text-align:right;">Rate</th>
            <th style="width:13%; text-align:right;">Amount</th>
        </tr>
    </thead>
    <tbody>
        {% for key, row in grouped.items() %}
        <tr>
            <td style="text-align:center;">{{ loop.index }}</td>
            <td>
                <strong>{{ row.description.split(' - ')[0].split('_')[0].split('-')[0] }}</strong>
            </td>
            <td style="text-align:center;">{{ row.type }}</td>
            <td style="text-align:center;">{{ row.qty }} {{ row.uom }}</td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}
            </td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}
            </td>
        </tr>
        {% endfor %}

        {% for item in normal_items %}
        <tr>
            <td style="text-align:center;">{{ grouped|length + loop.index }}</td>
            <td>
                <strong>{{ item.item_name.split(' - ')[0].split('_')[0].split('-')[0] }}</strong>
            </td>
            <td style="text-align:center;">{{ item.item_group }}</td>
            <td style="text-align:center;">{{ item.qty }} {{ item.uom }}</td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}
            </td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>

<!-- TAXES TABLE -->
{% if doc.taxes %}
<table class="table table-bordered" width="100%" cellspacing="0" cellpadding="6" style="margin-top:15px;">
    <thead style="background-color:#d9a7ff;">
        <tr>
            <th style="width:10%; text-align:center;">Sr</th>
            <th style="width:45%;">Type</th>
            <th style="width:20%; text-align:right;">Amount</th>
            <th style="width:25%; text-align:right;">Total</th>
        </tr>
    </thead>
    <tbody>
        {% for tax in doc.taxes %}
        <tr>
            <td style="text-align:center;">{{ loop.index }}</td>
            <td><strong>{{ tax.description }}</strong></td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(tax.tax_amount, currency=doc.currency) }}
            </td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(tax.total, currency=doc.currency) }}
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>
{% endif %}

<!-- PAYMENT SCHEDULE TABLE -->
{% if doc.payment_schedule %}
<table class="table table-bordered" width="100%" cellspacing="0" cellpadding="6" style="margin-top:15px;">
    <thead style="background-color:#d9a7ff;">
        <tr>
            <th style="width:10%; text-align:center;">Sr</th>
            <th style="width:25%; text-align:center;">Due Date</th>
            <th style="width:20%; text-align:right;">Invoice Portion (%)</th>
            <th style="width:20%; text-align:right;">Payment Amount</th>
            <th style="width:25%; text-align:right;">Outstanding</th>
        </tr>
    </thead>
    <tbody>
        {% for row in doc.payment_schedule %}
        <tr>
            <td style="text-align:center;">{{ loop.index }}</td>
            <td style="text-align:center;">{{ frappe.format_date(row.due_date) }}</td>
            <td style="text-align:right;">{{ row.invoice_portion }}%</td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(row.payment_amount, currency=doc.currency) }}
            </td>
            <td style="text-align:right;">
                {{ frappe.utils.fmt_money(row.outstanding, currency=doc.currency) }}
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>
{% endif %}

<!-- ITEM GROUP SUMMARY TABLE -->
{% set group_map = {} %}
{% for item in doc.items %}
    {% set key = item.item_group %}
    {% if key in group_map %}
        {% set _ = group_map.update({
            key: {
                "qty": group_map[key]["qty"] + item.qty,
                "amount": group_map[key]["amount"] + item.amount,
                "uom": item.uom
            }
        }) %}
    {% else %}
        {% set _ = group_map.update({
            key: {
                "qty": item.qty,
                "amount": item.amount,
                "uom": item.uom
            }
        }) %}
    {% endif %}
{% endfor %}

<table class="group-table">
    <thead>
        <tr>
            <th>Item Group</th>
            <th>Quantity</th>
            <th>Amount</th>
        </tr>
    </thead>
    <tbody>
        {% for group, values in group_map.items() %}
        <tr>
            <td>{{ group }}</td>
            <td>{{ values.qty }} {{ values.uom }}</td>
            <td>{{ frappe.utils.fmt_money(values.amount, currency=doc.currency) }}</td>
        </tr>
        {% endfor %}
    </tbody>
</table>

<!-- TOTALS -->
<div style="text-align: right; line-height: 1.4;">
    <div style="font-weight: bold; color: #000000; font-size: 14px;">
        Product QTY {{ doc.total_qty }}
    </div>
</div>

<div style="text-align: right; line-height: 1.4;">
    <div style="font-weight: bold; color: #000000; font-size: 14px;">
        Order Total {{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}
    </div>
</div>

<div style="text-align: right; line-height: 1.4;">
    <div style="font-weight: bold; color: #000000; font-size: 14px;">
        Amount Paid {{ frappe.utils.fmt_money(doc.advance_paid, currency=doc.currency) }}
    </div>
</div>

<div style="text-align: right; line-height: 1.4;">
    <div style="font-weight: bold; color: #000000; font-size: 14px;">
        Outstanding {{ frappe.utils.fmt_money(doc.grand_total - doc.advance_paid, currency=doc.currency) }}
    </div>
</div>

<!-- PAYMENT INFO FOOTER -->
<div style="display: flex; justify-content: space-between; margin-top: 270px;">
    <div style="text-align: left; width: 50%;">
        <strong>WIRE/ACH PAYMENT INFORMATION</strong><br>
        Bank name: Blue Sky Bank<br>
        Account number: 000020037008<br>
        Routing number: 103101877
    </div>
</div>

{% if doc.custom_terms %}
<div style="margin-top: 20px; text-align: left;">
    <strong>Notes:</strong><br>
    {{ doc.custom_terms }}
</div>
{% endif %}
